{
"spec": "This plan adds CSV and Markdown output formats to the exporter tool, ensuring they handle missing keys gracefully by outputting empty cells. It introduces a --fields CLI argument to allow users to select and order specific columns for any format. The --list-formats CLI argument is updated to include the new formats in its output. Existing JSON and text modules remain untouched to preserve byte-for-byte compatibility, while the registry is extended to support the new writers. All new functionality is validated through dedicated unit and integration tests.",
"stack": "Python, csv, markdown, pytest",
"tasks": [
  {
    "id": 1,
    "title": "Implement CSV writer module with header and quoting logic",
    "files": [
      "exporter/formats/csv_fmt.py"
    ],
    "test": "tests/test_csv.py checks header row, quoting, and missing values."
  },
  {
    "id": 2,
    "title": "Implement Markdown writer module with table formatting and pipe escaping",
    "files": [
      "exporter/formats/md_fmt.py"
    ],
    "test": "tests/test_md.py checks table formatting, escaped pipes, and missing values."
  },
  {
    "id": 3,
    "title": "Update formats registry to include new CSV and Markdown writers",
    "files": [
      "exporter/formats/__init__.py"
    ],
    "test": "tests/test_registry.py checks new formats appear in names()."
  },
  {
    "id": 4,
    "title": "Add --fields CLI argument for column selection and ordering",
    "files": [
      "exporter/cli.py"
    ],
    "test": "tests/test_cli.py checks field selection and ordering for all formats."
  },
  {
    "id": 5,
    "title": "Add --list-formats CLI argument to display available formats",
    "files": [
      "exporter/cli.py"
    ],
    "test": "tests/test_cli.py checks output includes csv and markdown."
  },
  {
    "id": 6,
    "title": "Ensure default output is stdout when no path is provided",
    "files": [
      "exporter/cli.py"
    ],
    "test": "tests/test_cli.py checks stdout output for all formats."
  },
  {
    "id": 7,
    "title": "Verify JSON output remains unchanged after refactoring",
    "files": [
      "tests/test_json.py"
    ],
    "test": "tests/test_json.py asserts byte-for-byte equality with baseline."
  },
  {
    "id": 8,
    "title": "Integration test for mixed-key records across new formats",
    "files": [
      "tests/test_integration.py"
    ],
    "test": "tests/test_integration.py checks empty cells for missing keys in csv/md."
  }
]
}

